; Keyboard interrupt-side poll and acknowledge service.
keyboard_interrupt_service:
	bit 0,(iy-07eh)
	jr nz,$+32
	push ix
	ld ix,(0c223h)
	in a,(050h)
	ld c,a	
	ld a,040h
	out (05bh),a
	call 0407dh
	jr nz,$+5
	call 0055fh
	ld a,c	
	call nz,08099h
	call 00530h
	pop ix
	ret	

